// Marco's Snow mark for the contract header band.
//
// The TIGHT square lockup (snowflake + SNOW), supplied by Marco and used as
// given — light blue, not recoloured. Note for anyone revisiting this: the
// band behind it is #0d6cb5, so the mark sits at roughly a 2:1 contrast ratio
// and prints faint. That was raised and chosen deliberately; the previous
// white MARCO'S SNOW lockup from the reference document is in git history if
// it ever needs restoring.
//
// Downscaled to 300px square: it renders at 38px CSS (~119 device pixels at
// 300dpi), so the 734px original was carrying weight the bundle didn't need.
export const SNOW_LOGO_DATA_URI = 'data:image/png;base64,';

// DARK VARIANT — the same mark, same geometry, recoloured to the brand blue
// #0d6cb5 so it reads on WHITE. This is the print fallback: if a print path
// drops background colours (Chrome's 'Background graphics' unticked, or a PDF
// engine that ignores print-color-adjust), the blue band paints white and the
// light mark disappears into it. The band stacks this underneath the light one
// and covers it with an opaque band-coloured layer — that cover is itself a
// background, so it vanishes in exactly the case the dark mark is needed.
// Generated from SNOW_LOGO_DATA_URI by recolouring every non-transparent
// pixel; the alpha channel is untouched, so the two layers register exactly.
export const SNOW_LOGO_DARK_DATA_URI = 'data:image/png;base64,';
